<template><view class="page assistant-page"><view class="page-return" @click="backHome">‹ 返回首页</view><view class="history card"><view class="row"><text class="title">对话历史</text><text class="link" @click="newSession">+ 新对话</text></view><scroll-view scroll-x class="history-scroll"><view class="history-row"><text v-for="item in sessions" :key="item.id" :class="['history-chip',{active:item.id===activeId}]" @click="choose(item.id)">{{ item.title }}</text></view></scroll-view></view><view class="card chat"><scroll-view scroll-y class="messages" :scroll-top="scrollTop"><view v-for="(message,index) in activeMessages" :key="index" :class="['bubble',message.role]"><text>{{ message.content }}</text><text v-if="message.evidence" class="evidence">{{ message.evidence }}</text></view></scroll-view><view class="suggestions"><text @click="question='请解读我最新的钱格测试结果'">解读最新钱格</text><text @click="question='我日常生活还能花多少？'">日常还能花多少？</text><text @click="question='哪类消费最高？'">哪类消费最高？</text></view><view class="input-row"><input v-model="question" confirm-type="send" @confirm="send" placeholder="问问你的钱该怎么安排" /><button @click="send">发送</button></view></view></view></template>
<script setup>
import { computed, nextTick, onMounted, ref } from 'vue'; import { api } from '../../utils/api'
const sessions=ref([]), activeId=ref(null), question=ref(''), scrollTop=ref(0); const activeMessages=computed(()=>sessions.value.find(item=>item.id===activeId.value)?.messages||[])
async function load(){sessions.value=await api('/assistant/sessions');if(!activeId.value&&sessions.value.length)activeId.value=sessions.value[0].id;scroll()}
function choose(id){activeId.value=id;scroll()};async function newSession(){const session=await api('/assistant/sessions',{method:'POST'});sessions.value.unshift(session);activeId.value=session.id;scroll()}
async function send(){if(!question.value.trim())return;const text=question.value;question.value='';const reply=await api('/assistant/chat',{method:'POST',data:{sessionId:activeId.value,question:text}});await load();activeId.value=reply.sessionId;scroll()}
function scroll(){nextTick(()=>scrollTop.value=100000)}
async function init(){await load();const pending=uni.getStorageSync('pendingAssistantQuestion');if(pending){uni.removeStorageSync('pendingAssistantQuestion');const text=typeof pending==='string'?pending:pending.text;if(typeof pending==='object'&&pending.createNew)await newSession();question.value=text;await send()}}
onMounted(init)
function backHome(){ uni.reLaunch({url:'/pages/index/index'}) }
</script><style scoped>.assistant-page{display:flex;flex-direction:column;height:100vh}.page-return{display:inline-block;align-self:flex-start;color:#58744e;background:#eef8ea;border:1rpx solid #dcebd6;border-radius:999rpx;font-size:24rpx;padding:10rpx 18rpx;margin:0 0 18rpx}.history{padding-bottom:16rpx}.link{color:#58744e;font-size:24rpx}.history-scroll{white-space:nowrap;margin-top:20rpx}.history-row{display:flex;gap:12rpx}.history-chip{display:inline-block;padding:11rpx 18rpx;background:#f3f7f0;color:#6c8066;border-radius:999rpx;font-size:23rpx}.history-chip.active{background:#CEEBC5;color:#58744e;font-weight:700}.chat{flex:1;display:flex;flex-direction:column;min-height:0}.messages{flex:1;height:0}.bubble{max-width:85%;margin-bottom:16rpx;padding:18rpx;border-radius:18rpx;font-size:27rpx;line-height:1.6;display:flex;flex-direction:column}.bubble.assistant{background:#f1f8ee}.bubble.user{background:#CEEBC5;color:#58744e;margin-left:auto}.evidence{font-size:20rpx;color:#6c8066;margin-top:10rpx}.suggestions{display:flex;gap:12rpx;overflow:auto;padding:16rpx 0}.suggestions text{white-space:nowrap;font-size:21rpx;padding:9rpx 14rpx;border:1rpx solid #dcebd6;border-radius:999rpx;color:#58744e}.input-row{display:flex;gap:12rpx;border-top:1rpx solid #edf2ea;padding-top:16rpx}.input-row input{flex:1;background:#f8fcf6;border-radius:14rpx;padding:14rpx}.input-row button{margin:0;background:#87aa78;color:#fff;font-size:25rpx;line-height:64rpx}</style>
